"""
Injeta ATCUD, QR Code, hash de assinatura e texto de certificacao nos
Print Formats NATIVOS da ERPNext para os 4 doctypes fiscais (Sales
Invoice, POS Invoice, Payment Entry, Delivery Note). Ver plano:
compliance para print formats nativos, 2026-09-02, e backup em
utils/native_print_format_backup.py.

Porque isto existe (nao basta editar a DB uma vez): estes Print Formats
pertencem aos modulos Accounts/Selling/Stock da propria ERPNext e sao
descobertos por frappe.model.sync.sync_all() em qualquer bench
migrate/update a partir dos .json da app erpnext - uma reimportacao (que
apaga tudo exceto "disabled") acontece sempre que o "modified" do
ficheiro fonte for mais recente que o do registo na DB. Por isso esta
funcao e chamada em after_migrate (hooks.py) e reaplica o conteudo
sempre que o marcador PT_COMPLIANCE_MARKER nao for encontrado no html
atual - tanto serve para o rollout inicial como para a auto-reparacao.

Caso especial: "Sales Auditing Voucher", "Sales Invoice Return" e "Bank
and Cash Payment Voucher" tem o seu HTML real servido a partir de um
ficheiro .html irmao dentro da propria app erpnext
(frappe/www/printview.py::get_print_format() da sempre prioridade a um
ficheiro em disco do modulo do Print Format, quando existe, sobre o
campo "html" da DB) - editar apenas o campo html na DB nao teria
qualquer efeito nestes 3. A correcao e mudar o "module" destes 3 de
"Accounts" para "Portugal Compliance", para que a resolucao de caminho
deixe de encontrar esse ficheiro e passe a usar o html da DB.
"""

import frappe
from portugal_compliance.utils.document_hooks import _any_active_portuguese_company

PT_COMPLIANCE_MARKER = "<!-- pt-compliance-injected v1 -->"

# Print Formats cujo html real vem de um ficheiro .html irmao dentro da
# app erpnext, que sombreia sempre o campo Print Format.html - precisam
# de ser "adotados" pelo modulo Portugal Compliance para a injecao ter
# efeito (ver docstring do modulo).
DISK_SHADOWED_FORMATS = {
	"Sales Auditing Voucher",
	"Sales Invoice Return",
	"Bank and Cash Payment Voucher",
}


def ensure_native_print_formats_compliant(app_name=None):
	"""Chamada em after_migrate E em after_app_install. Garante que os Print
	Formats nativos da ERPNext para os 4 doctypes fiscais tem ATCUD/QR/
	assinatura/texto de certificacao injetados. Idempotente: so escreve
	quando o marcador nao esta presente no html atual, ou (para os 3
	disk-shadowed) quando o module ainda nao e o nosso - serve tanto para o
	rollout inicial (bench migrate) como para uma instalacao nova (bench
	install-app, onde after_migrate NAO corre) e para a auto-reparacao apos
	um bench update que reimporte o original. `app_name` e aceite e
	ignorado apenas porque after_app_install invoca os seus hooks com
	frappe.get_attr(fn)(name) - ver hooks.py."""
	if not _any_active_portuguese_company():
		return

	fixed = []
	for name, html in NATIVE_PRINT_FORMAT_HTML.items():
		if not frappe.db.exists("Print Format", name):
			continue

		current_html = frappe.db.get_value("Print Format", name, "html") or ""
		current_module = frappe.db.get_value("Print Format", name, "module")

		needs_module_fix = name in DISK_SHADOWED_FORMATS and current_module != "Portugal Compliance"
		needs_html_fix = PT_COMPLIANCE_MARKER not in current_html

		if not needs_module_fix and not needs_html_fix:
			continue

		try:
			doc = frappe.get_doc("Print Format", name)
			doc.html = html
			if name in DISK_SHADOWED_FORMATS:
				doc.module = "Portugal Compliance"
			doc.save(ignore_permissions=True)
			fixed.append(name)
		except Exception:
			frappe.log_error(
				title="ensure_native_print_formats_compliant",
				message=frappe.get_traceback(),
			)

	if fixed:
		frappe.db.commit()
		frappe.logger().info(
			f"ensure_native_print_formats_compliant: aplicado/reparado em {fixed}"
		)


import re

# "Company Letterhead - Grey" e tambem um documento standard servido a
# partir de erpnext/accounts/letter_head/company_letterhead___grey/ -
# mesmo risco de sync_all() a repor o <img src="{{ frappe.utils.get_url(...)
# }}"> original num bench update futuro. Esse URL simples nunca carrega
# dentro do cabecalho REPETIDO do PDF real (nao no preview do Desk):
# frappe.utils.pdf.prepare_options() extrai e escreve em disco o
# ficheiro temporario do cabecalho ANTES de correr inline_private_images()
# na mesma funcao - bug de ordem de operacoes confirmado ao vivo em
# 2026-09-02 (ver frappe/utils/pdf.py: read_options_from_html() corre
# antes de inline_private_images() dentro de prepare_options()).
# get_company_logo_base64() (jinja_methods.py) contorna isto por completo,
# gerando o base64 no momento do render do template.
_LETTERHEAD_LOGO_SRC_PATTERN = re.compile(
	r'<img src="\{\{\s*frappe\.utils\.get_url\(company_logo\)\s*\}\}"\s*/>'
)


def ensure_letter_head_logo_uses_base64(app_name=None):
	"""Chamada em after_migrate E em after_app_install. Garante que o <img>
	do logo na letterhead "Company Letterhead - Grey" usa
	get_company_logo_base64() em vez de frappe.utils.get_url() - idempotente
	e auto-reparavel pelo mesmo motivo e mecanismo de
	ensure_native_print_formats_compliant() acima, incluindo a mesma razao
	para aceitar e ignorar `app_name`."""
	if not _any_active_portuguese_company():
		return
	name = "Company Letterhead - Grey"
	if not frappe.db.exists("Letter Head", name):
		return
	content = frappe.db.get_value("Letter Head", name, "content") or ""
	if "get_company_logo_base64" in content:
		return
	if not _LETTERHEAD_LOGO_SRC_PATTERN.search(content):
		return
	new_content = _LETTERHEAD_LOGO_SRC_PATTERN.sub(
		"<img src=" + chr(34) + "{{ get_company_logo_base64(doc.company) }}" + chr(34) + " />", content
	)
	try:
		doc = frappe.get_doc("Letter Head", name)
		doc.content = new_content
		doc.save(ignore_permissions=True)
		frappe.db.commit()
		frappe.logger().info(f"ensure_letter_head_logo_uses_base64: aplicado/reparado em {name}")
	except Exception:
		frappe.log_error(
			title="ensure_letter_head_logo_uses_base64",
			message=frappe.get_traceback(),
		)


